"""Build a standalone, atom-first exploratory research report; no external assets."""
import json,html
from pathlib import Path
from analyze_information_flow import ROOT,OUT
D=json.loads((OUT/'analysis.json').read_text());S=json.loads((OUT/'summary.json').read_text())
def pct(x):return '—' if x is None else f'{100*x:.1f}%'
def pp(x):return f'{100*x:+.1f} pp'
def interval(r):return f"{pp(r['mean'])} [{100*r['lo']:+.1f}, {100*r['hi']:+.1f}]"
def esc(x):return html.escape(str(x))
priv=next(r for r in S['contrasts'] if r['phase']=='team-vote' and r['metric']=='new_related')
eqpriv=next(r for r in S['contrasts'] if r['phase']=='team-vote' and r['metric']=='new_equivalent')
inter=next(r for r in S['interactions'] if r['metric']=='new_related')
body='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Avalon · Atomic information flow</title><style>
:root{--ink:#172d43;--muted:#526779;--blue:#2364ad;--teal:#118378;--orange:#c76c20;--red:#b84250;--line:#dce5eb;--bg:#f5f8fa}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1200px;margin:auto;padding:46px 28px 100px}h1{font-size:42px;line-height:1.2;max-width:900px}h2{font-size:27px;margin:0 0 16px}h3{font-size:20px}p{max-width:1000px}section{background:white;border:1px solid var(--line);border-radius:15px;padding:30px;margin:25px 0;scroll-margin-top:25px}nav{display:flex;flex-wrap:wrap;gap:12px}a{color:var(--blue)}.eyebrow{color:var(--teal);font-weight:700;letter-spacing:.12em}.lead{font-size:21px}.muted,.note{color:var(--muted);font-size:14px}.note{border-left:3px solid #95b6d3;padding:10px 16px;background:#f4f8fc}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{background:#edf5fb;border-radius:12px;padding:20px}.card strong{display:block;font-size:31px;color:var(--blue)}.row{display:flex;flex-wrap:wrap;align-items:center;gap:14px;margin:16px 0}select{max-width:100%;font:inherit;border:1px solid #aebfcc;border-radius:6px;background:white;padding:6px 10px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#edf3f7;position:sticky;top:0}td.num{font-variant-numeric:tabular-nums;white-space:nowrap}.scroll{overflow:auto}.bar{display:inline-block;height:9px;background:var(--blue);border-radius:3px;vertical-align:middle;margin-right:8px}.pill{display:inline-block;border-radius:20px;background:#e5edf5;padding:2px 9px;font-size:12px}.warn{background:#fff2e8;border-color:#dabba2}.cols{display:grid;grid-template-columns:1fr 1fr;gap:24px}.metric{font-size:26px;font-weight:700;color:var(--teal)}svg{width:100%;display:block}svg text{font-family:inherit}button{font:inherit;cursor:pointer}.detail{padding:16px;background:#f1f6fa;border-radius:10px;min-height:95px;overflow-wrap:anywhere}.small{font-size:13px}code{font-size:13px;background:#edf2f5;padding:2px 4px}details{margin:15px 0}summary{cursor:pointer;font-weight:600}.truth-false{color:var(--red)}.truth-true{color:var(--teal)}@media(max-width:760px){main{padding:20px 12px}.cards,.cols{grid-template-columns:1fr}section{padding:20px}h1{font-size:32px}}
</style><main><div class="eyebrow">FACTFLOW / AVALON / 2026-09-08</div><h1>谁的命题进入了谁的理由？<br>从原子事实重建游戏中的信息选择</h1><p class="lead">同样坐在公开讨论桌前，不同角色依赖同伴的方式，可能只在进入决策理由时才显露。分析对象是命题的跨人、跨渠道和跨表达方式流动。</p><p class="muted">10 局、5 人、自博弈；本地 AvalonBench 风格实现。固定模型 DeepSeek-v4-flash，固定全员广播。探索性结果，尚无跨模型或拓扑干预。全部核心指标来自冻结的原子产物，无新增模型调用。</p><nav><a href="#definitions">定义与数据</a><a href="#channels">角色 × 渠道</a><a href="#camp">来源选择</a><a href="#matrix">交互矩阵</a><a href="#truth">真假命题图</a><a href="#modality">表达变化</a><a href="#next">研究方向</a><a href="#limits">复现与边界</a></nav>'''
body+=f'''<section><div class="cards"><div class="card"><strong>{sum(g['mentions'] for g in D['games']):,}</strong>抽取后的原子命题出现<br><span class="small">包含公开、私有及环境来源</span></div><div class="card"><strong>{100*priv['mean']:.1f} pp</strong>Servant 相比 Merlin，在私有投票理由中的同伴复用差距<br><span class="small">10 局配对平均</span></div><div class="card"><strong>{pct(S['oneway_share'])}</strong>非无关 NLI 候选对属于单向蕴含<br><span class="small">不是“传播中信息损失”的比例</span></div></div></section>'''
body+='''<section id="definitions"><h2>1 · 我们在测什么</h2><p>每局有 Merlin（知道谁是 Evil）、两名 Servant（不知道他人身份）、Minion 和 Assassin（知道 Evil 队友）。前三者属于 Good；后两者属于 Evil。<b>角色同时改变信息权限与目标，因此本语料不能把角色差异拆成“人格效应”或“信息效应”。</b></p><div class="scroll"><table><tr><th>对象</th><th>具体定义</th><th>如何使用</th></tr><tr><td>命题与命题出现</td><td><code>facts</code> 是等价簇；<code>mentions</code> 是带出处的抽取命题。同一事实在一个事件内只计一次，在不同事件中再出现可分别计数。</td><td>覆盖率的单位为 <b>(event_id, fact_id)</b>。不是 token，也不是一条 NLI 边。</td></tr><tr><td>表达类型 modality</td><td>record：抽取器标成游戏记录；assertion：断言；belief：相信；speculation：猜测；directive：建议；intention：意图；strategy：策略。</td><td>它描述抽取器认为命题如何被表达；不自动等于真值或实际心理状态。</td></tr><tr><td>公开 → 公开</td><td>先前可见的其他玩家公开命题，与当前公开命题形成直接 NLI 关系。</td><td>测公开内容复用。</td></tr><tr><td>公开 → 私有</td><td>其他玩家公开命题，与后来的私有投票 / 刺杀理由命题形成直接关系。</td><td>测内容进入决策理由；不能据此声称改变了投票，或读取了隐藏思维。</td></tr><tr><td>自持筛除</td><td>接收者之前自己已出现同一 fact_id，或有直接等价的先前自身命题，就排除。</td><td>公开历史和该玩家自己的私有历史均计入；避免把已说过的命题再算成新接收。</td></tr><tr><td>复用覆盖率</td><td>有合法同伴前驱且通过自持筛除的输出事实出现数 ÷ 该类输出全部事实出现数。</td><td>多个候选发送者不重复增加分子。无候选评分的输出仍在分母中；缺边不代表独立生成。</td></tr><tr><td>三个口径</td><td>相关：EQ + 两种单向蕴含；等价：只保留 EQ；非 record：相关，但边的两端都不是 record。</td><td>“非 record”仍包含判断、建议、策略等，不仅是身份主张。</td></tr></table></div><p class="note">同一讨论批次的五名玩家并行生成，彼此不可见；同一批私有投票也互不可见。event_id 的先后不是访问权限。私有理由从不因“投票结果公开”而变成公共输入。state 命题的跨 Quest 直接匹配不进入主统计。全员广播意味着合法先后匹配仍可能是共同推导，称“观察到的复用”，不作因果传输断言。</p></section>'''
body+=f'''<section id="channels"><h2>2 · 公开说得相似，决策理由的依赖却不同</h2><p>Servant − Merlin：公开讨论的复用差距为 <b>{interval(next(r for r in S['contrasts'] if r['phase']=='discussion' and r['metric']=='new_related'))}</b>；私有投票理由的差距为 <b>{interval(priv)}</b>。两种渠道差距之差为 <b>{interval(inter)}</b>，10 局中 {inter['positive_games']} 局同方向。</p><p>只计等价关系，私有渠道差距仍为 <b>{interval(eqpriv)}</b>。因此它不完全依赖把单向蕴含也计作复用。一个可检验的解释是：缺少身份先验的角色，更多借用公开命题来组织决策理由；公开发言本身却未必表现出更强依赖。</p><div class="row"><label>匹配口径 <select id="coverageMode"><option value="new_related">全部相关关系</option><option value="new_equivalent">仅等价</option><option value="new_nonrecord">排除 record 两端</option></select></label></div><div id="coverage"></div><p class="note">条形图显示合并分子 / 分母；文字结论先在每局合并同角色玩家，再求 10 局配对差值。二者不会完全相等。区间是按游戏重采样的 95% bootstrap 描述区间，不包含抽取与匹配误差，亦未校正探索多个指标。</p></section>'''
body+='''<section id="camp"><h2>3 · 阵营偏向：共同复述记录，还是选择同伴判断？</h2><p>Good 有三人，Evil 只有两人，不能直接比较来源边数。这里对每个被复用的目标命题，给最近可见的匹配发送者分配来源信用；同批并列发送者等分。再把 Evil 的实际来源份额，与接收者当时可见的其他玩家公开原子出现中的 Evil 份额作比较。</p><p><b>Good 的公开来源偏向在排除 record 后不稳定；私有理由中的非 record 来源偏向仍存在。</b>这让“共同重复游戏历史”和“选择谁的判断”可以分开测。Evil 各口径的游戏间区间普遍宽，不能宣布两阵营形成了对称回音室。</p><div class="row"><label>目标渠道 <select id="campChannel"><option value="public_to_public">公开讨论 / 提名</option><option value="public_to_private">私有投票 / 刺杀理由</option></select></label><label>口径 <select id="campMode"><option value="related">全部相关关系</option><option value="equivalent">仅等价</option><option value="nonrecord">排除 record</option></select></label></div><div id="campResults"></div><p class="note">负值表示 Evil 来源比其输入体量预期更少；这是按输入量作的描述基线，不是随机实验的零假设。来源池按命题出现计数，反映完整历史中的重复暴露；不控制语义相关性、事实质量与匹配候选选择。私有渠道的结果也不能理解为 Good 玩家知道了真实阵营。</p></section>'''
body+='''<section id="matrix"><h2>4 · 谁进入谁：角色交互矩阵</h2><p>行是发送角色，列是接收角色。每格为“被这个来源角色覆盖的目标命题出现 / 该接收角色的全部目标命题出现”。不同来源角色可能覆盖同一个目标，所以一列不能相加。Servant→Servant 指两名不同玩家，其他同角色对角线没有第二名玩家。</p><div class="row"><label>渠道 <select id="matrixChannel"><option value="public_to_public">公开 → 公开</option><option value="public_to_private">公开 → 私有</option></select></label><label>口径 <select id="matrixMode"><option value="related">全部相关</option><option value="equivalent">等价</option><option value="nonrecord">非 record</option></select></label></div><div id="matrixTable"></div><p class="note">矩阵是接收端覆盖，不是发送端说服成功率。角色人数与输出主题不同，不能单凭一个格子更深就判定该角色更有影响力。第三节提供了进一步的输入体量对照。</p></section>'''
body+='''<section id="truth"><h2>5 · 把真值挂到命题图上，而不是把低重合叫“欺骗”</h2><p>现成的原子命题允许对两类窄范围内容直接判真值：① 完整、无条件的单玩家 Good / Evil 身份句；② 明确的 Quest 人数要求。前者与隐藏角色标签比较，后者与规则元数据比较。解析覆盖不了假设、析取、模糊信任和大部分策略命题，全部留在范围外。</p><div class="cols"><div><h3>身份命题的渠道选择</h3><p>Evil 的公开身份命题有 <b>10/24</b> 与角色真值不符，私有投票理由为 <b>0/41</b>；Merlin 对应为 <b>0/18</b> 与 <b>0/50</b>。这是可解析原子出现的构成差异，不能推广为全部话语的说谎率。</p><p>Servant 的公开候选有 8/45 为假，说明错误内容也会由 Good 产生。候选中的个别假句来自抽取过度强化或拆坏析取，故不据此给玩家作诚信排名。</p></div><div><h3>规则错误属于哪一类流？</h3><p>第 10 局同一条错误命题 <b>“Quest 3 requires three players”</b>（实际应为 2）有 <b>10 个可解析原子出现</b>，跨 <b>3 名 Good 玩家</b>：公开 5 次、私有 5 次。既有的直接匹配图能连接其中若干出现。</p><p>但 Merlin 在 E52 的私有命题已经是这个错误，早于原子产物中的首次公开出现。因此图支持“跨人、跨渠道反复出现”，<b>不支持把后来的公开→Merlin 连线说成首次感染</b>。原子图暴露了归因边界。</p></div></div><p>下面显示选定命题的全部原子节点与本分析保留的直接匹配边。<b>横轴是可见性批次，纵轴是玩家；实心为公开，空心为私有。</b>点击节点查看完整原子文本与出处。灰色虚线表示目标此前已有自身等价事实，属于再现；它仍是关系边，但不进入“新接收”统计。</p><div class="row"><label>游戏 <select id="graphGame"></select></label><label>真值 <select id="graphTruth"><option value="false">假命题</option><option value="all">全部可判真值命题</option><option value="true">真命题</option></select></label></div><label>命题 <select id="graphFact" style="width:100%"></select></label><div class="scroll"><svg id="factGraph" viewBox="0 0 1120 520" role="img" aria-label="命题跨玩家与渠道的时间图"></svg></div><p id="graphCaption" class="note"></p><div id="atomDetail" class="detail">点击图中节点，阅读原子事实而非原始整段对话。</div><details><summary>显示全部可判真值命题的扩散清单</summary><div id="truthTable" class="scroll"></div></details><p class="note">这里的真值属于抽取后的命题。不是人工金标准；抽取会把条件句或信任表达强化为断言。身份句全句解析避免从 if 句内部抓取身份，但不能修复已经发生的上游错误。用于发掘可追踪的命题链，而非估计玩家整体欺骗能力。</p></section>'''
body+='''<section id="modality"><h2>6 · 内容相同，表达地位是否改变？</h2><p>只看等价匹配、合法跨人先后、并已筛除自持的目标命题。行是来源的 modality，列是目标的 modality。一个内容可以从“相信”变成“断言”，或者从“断言”被标成“记录”。这些变化在二元事实集合里会被压成同一个元素。</p><div id="modalityTable" class="scroll"></div><p class="note">每格按目标 (游戏、事件、事实) 去重；同一目标有多种来源类型时可进入多个格。跨格相加不是独立样本数。record 是抽取标签，不能把 assertion→record 自动称为“谎言洗白”；真正有力的检验是同时要求命题真值错误、合法来源及标签变化。当前窄范围真值命题不足以支持其发生率结论。</p><h3>图分析的一个阴性结果同样有用</h3><p>同批并行的相关匹配有 690 对，这些可以测独立趋同，不能画成轮内传播箭头。三个不同玩家之间也存在匹配相接的时间路径；然而公开历史对所有人可见，第三人可以直接读取第一人的原子来源。<b>仅仅发现 A→B→C 路径，不等于 B 是中介。</b>在这个数据集里，值得优先分析的是渠道与来源选择，而不是把长路径当作传播距离。</p></section>'''
body+='''<section id="next"><h2>7 · 可以继续做实的研究方向</h2><table><tr><th>问题</th><th>当前数据提供了什么</th><th>可执行的下一步</th></tr><tr><td><b>依赖究竟出现在发言，还是决定时？</b></td><td>公开与私有理由的角色差距不同；相关、等价、非 record 三个口径方向一致。</td><td>冻结一套离线原子标注，跨任务比较“公开→决策理由”的渠道交互；若增加语料，按游戏留出评估。无须每轮在线抽取。</td></tr><tr><td><b>共享事实还是共享判断，造成了表面阵营化？</b></td><td>排除 record 后，公开偏向不稳定；私有非 record 的输入量校正偏向仍存在。</td><td>用来源类型 × 接收渠道做分层图；先检验同类内容下的来源选择，避免把共同证据当成相互说服。</td></tr><tr><td><b>错误共识从哪条输入路径形成？</b></td><td>身份假句和规则假句均可挂真值标签；同一条规则假句跨 Good 玩家、公开与私有出现。</td><td>离线确定错误命题子图，区分独立首次出现、自持、合法同伴前驱和新接收。再用新游戏干预单条命题的可见性；不要把后出现直接当采纳。</td></tr><tr><td><b>正确原子被公开后，帮助了队友还是对手？</b></td><td>同一来源可分别连接队友公开表达与对手私有理由，图里可以同时保留两种出口。</td><td>先扩大带真值的原子类别，再测“同一原子→队友理由 / 对手推断”的双重去向。刺杀结果只能作末端标签，当前 9 次刺杀不足以训练泄露预测器。</td></tr><tr><td><b>怎样改 agent 框架？</b></td><td>高质量身份信息与错误程序命题可并存；更多流动不自动意味着更好表现。</td><td>由离线结果提出固定策略：把可核验规则与玩家判断分开输入；对程序规则调用确定性检查；保留判断命题的来源及 modality。先做对照实验，再谈收益；不需要在线运行完整抽取匹配。</td></tr><tr><td><b>什么图量值得跨任务推广？</b></td><td>接收覆盖、来源份额校正、渠道交互、自持筛除和类型变化不依赖 Avalon 的专有语义。</td><td>相同图定义可用于讨论、协作写作及有私有材料的推理任务。真值标签随任务更换；不强求自动识别不可操作化的“术语漂移”。</td></tr></table><p>相对只测初始事实在各 agent 中保留多少，这些问题需要<b>发送者—接收者关系、实际可见性、表达渠道、命题类型和动态生成的新命题</b>。核心贡献应落在这些可复现的交互测量，而非再添一个存活率指标。</p></section>'''
body+='''<section id="limits"><h2>8 · 证据边界与复现</h2><p><b>输入：</b><code>experiments/avalon_5p_deepseek_v4_flash/*.nli.store.json</code>，完整 10 局；失败 smoke run 不入语料。原子文本、事实簇、关系和 provenance 是测量输入。trace 仅提供角色 / 规则真值、相位时序及结局标签；原始话语没有进入最终指标计算。</p><p><b>匹配：</b>Qwen3-14B，双方向共同阈值 5.28，BGE blocker 0.62、top_k 20、union_min 0.85。阈值来自已有 oracle 的拟合，并非独立调阈后在 Avalon 上评估；本报告不把历史拟合准确率搬成此语料准确率。单向关系描述命题强弱，不等于错误或质量损失。</p><p><b>统计：</b>主对比按游戏聚合 / 配对，10,000 次 bootstrap，固定随机种子。10 局均为同一模型和固定广播设计；缺少跨模型、拓扑和私有信息权限的独立对照。覆盖率是已抽取、已匹配图上的描述，不包含系统未抽出的内容。来源信用是观察口径，不能排除共同推导。</p><p><b>没有新增生成、抽取、标注或匹配调用。</b>原产物保持不变。身份与规则的窄范围语义键是对所有 10 局统一应用的离线解析，不回写事实簇。早期从原话提炼的投票正确率 / 规则错误计数已从本报告移除。</p><pre class="small">.venv/bin/python experiments/avalon/analyze_information_flow.py
.venv/bin/python experiments/avalon/summarize_information_flow.py
.venv/bin/python experiments/avalon/build_information_flow_report.py</pre><p><a href="data/avalon-flow/analysis.json">基础测量 JSON / 输入 SHA256</a> · <a href="data/avalon-flow/summary.json">汇总与完整原子子图 JSON</a> · <a href="data/avalon-flow/turns.csv">逐事件分子分母 CSV</a> · <a href="data/avalon-flow/claims.csv">身份命题候选 CSV</a> · <a href="2026-09-08-avalon-atomic-flow.md">研究记录 Markdown</a></p></section><footer class="muted">FactFlow · 离线原子信息流探索 · 2026-09-08</footer></main>'''
js=r'''
const $=x=>document.getElementById(x),P=x=>x==null?'—':(100*x).toFixed(1)+'%',PP=x=>(x>=0?'+':'')+(100*x).toFixed(1)+' pp',E=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),roles=['Merlin','Servant','Minion','Assassin'];
const ci=r=>`${PP(r.mean)} [${(100*r.lo).toFixed(1)}, ${(100*r.hi).toFixed(1)}]`;
function cov(){let k=$('coverageMode').value; $('coverage').innerHTML='<table><tr><th>角色</th><th>公开讨论：命题覆盖</th><th>私有投票理由：命题覆盖</th></tr>'+roles.map(role=>'<tr><td>'+role+'</td>'+['discussion','team-vote'].map(phase=>{let r=S.coverage.find(r=>r.role===role&&r.phase===phase),v=r[k]/r.n;return `<td><span class="bar" style="width:${v*210}px"></span><b>${P(v)}</b> · ${r[k]}/${r.n}</td>`}).join('')+'</tr>').join('')+'</table>'}
function camp(){let rr=S.camp.filter(r=>r.channel===$('campChannel').value&&r.mode===$('campMode').value);$('campResults').innerHTML='<table><tr><th>接收阵营</th><th>Evil 来源份额<br>游戏平均</th><th>按输入量预期份额<br>游戏平均</th><th>实际 − 预期<br>95% 描述区间</th><th>覆盖目标 / 总目标</th></tr>'+rr.map(r=>{let avg=k=>r.games.reduce((a,x)=>a+x[k],0)/r.games.length;return `<tr><td>${r.camp}</td><td>${P(avg('observed'))}</td><td>${P(avg('expected'))}</td><td><b>${ci(r.diff)}</b><br>${r.diff.n} 局</td><td>${r.matched}/${r.atoms}</td></tr>`}).join('')+'</table>'}
function matrix(){let rr=S.matrix.filter(r=>r.channel===$('matrixChannel').value&&r.mode===$('matrixMode').value);$('matrixTable').innerHTML='<table><tr><th>发送 ↓ / 接收 →</th>'+roles.map(x=>'<th>'+x+'</th>').join('')+'</tr>'+roles.map(a=>'<tr><th>'+a+'</th>'+roles.map(b=>{let r=rr.find(x=>x.sender===a&&x.receiver===b);return `<td style="background:rgba(35,100,173,${Math.min(.5,r.pooled*4)})"><b>${P(r.pooled)}</b><br>${r.hits}/${r.targets}</td>`}).join('')+'</tr>').join('')+'</table>'}
function modalities(){let tags=['record','assertion','belief','speculation','directive','strategy','intention'];$('modalityTable').innerHTML='<table><tr><th>来源 ↓ / 目标 →</th>'+tags.map(t=>'<th>'+t+'</th>').join('')+'</tr>'+tags.map(a=>'<tr><th>'+a+'</th>'+tags.map(b=>{let r=S.modality.find(x=>x.source===a&&x.target===b);return `<td style="background:rgba(17,131,120,${Math.min(.48,r.n/100)})">${r.n||'·'}${r.n?'<br><span class="small">'+r.games+' 局</span>':''}</td>`}).join('')+'</tr>').join('')+'</table>'}
function facts(){let rows=S.truth_facts.filter(r=>r.game===$('graphGame').value&&($('graphTruth').value==='all'||String(r.truth)===$('graphTruth').value));$('graphFact').innerHTML=rows.map(r=>`<option value="${E(r.key)}">${r.truth?'真':'假'} · ${E(r.text)} · 公开 ${r.public_agents} 人 / 私有 ${r.private_agents} 人</option>`).join('');graph()}
function graph(){let gid=$('graphGame').value,f=S.truth_facts.find(r=>r.game===gid&&r.key===$('graphFact').value),svg=$('factGraph');if(!f){svg.innerHTML='<text x="30" y="60">该游戏没有符合筛选条件的可解析命题。</text>';$('graphCaption').textContent='空集合不表示没有其他错误；这里只覆盖两类可判真值命题。';return}let g=S.atomic_cases[gid],ids=[...new Set(f.mentions)],nodes=ids.map(id=>({id,...g.mentions[id]})).filter(n=>n.agent),batches=[...new Set(nodes.map(n=>n.batch))].sort((a,b)=>a-b),xs=b=>170+(batches.indexOf(b)+.5)*900/batches.length,ys=p=>65+Number(p.slice(1))*86,byid=Object.fromEntries(nodes.map(n=>[n.id,n])),edges=g.edges.filter(r=>byid[r.source_mid]&&byid[r.target_mid]);
let out='<defs><marker id="arr" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#688398"/></marker></defs>';
for(let p=0;p<5;p++){out+=`<text x="10" y="${ys('P'+p)+5}" fill="#263f54" font-size="15">P${p} · ${g.roles['P'+p]}</text><line x1="165" x2="1090" y1="${ys('P'+p)}" y2="${ys('P'+p)}" stroke="#e0e9ef"/>`}
for(let b of batches)out+=`<line x1="${xs(b)}" x2="${xs(b)}" y1="32" y2="441" stroke="#eef2f5"/><text x="${xs(b)}" y="469" text-anchor="middle" font-size="12" fill="#536a7c">批次 ${b}</text>`;
for(let r of edges){let a=byid[r.source_mid],b=byid[r.target_mid],x=xs(a.batch),y=ys(a.agent),xx=xs(b.batch),yy=ys(b.agent),c=r.prior_self?'#a6b2bc':r.kind==='equivalent'?'#2364ad':r.kind==='weaken'?'#c76c20':'#7854aa';out+=`<path d="M${x+11},${y} C${(x+xx)/2},${y+18} ${(x+xx)/2},${yy+18} ${xx-13},${yy}" fill="none" stroke="${c}" stroke-width="1.8" ${r.prior_self?'stroke-dasharray="5 4"':''} marker-end="url(#arr)"><title>${E(r.kind)} · ${r.prior_self?'已有自身命题':'通过自持筛除'}</title></path>`}
for(let n of nodes){let x=xs(n.batch),y=ys(n.agent),pub=n.visibility==='public';out+=`<g data-mid="${n.id}" tabindex="0" style="cursor:pointer"><circle cx="${x}" cy="${y}" r="12" fill="${pub?'#2364ad':'white'}" stroke="#2364ad" stroke-width="2.5"/><text x="${x}" y="${y-21}" text-anchor="middle" font-size="12" fill="#263f54">E${n.event_id}</text><text x="${x}" y="${y+31}" text-anchor="middle" font-size="11" fill="#536a7c">${E(n.modality)}</text><title>${E(n.text)}</title></g>`}out+='<text x="170" y="505" fill="#526779" font-size="12">实心：公开　空心：私有　蓝边：等价　橙边：弱化　紫边：细化　灰虚线：已有自身等价命题</text>';svg.innerHTML=out;
$('graphCaption').textContent=`${f.text} · ${nodes.length} 个原子节点，${new Set(nodes.map(n=>n.agent)).size} 名玩家；${edges.length} 条合法直接关系，其中 ${edges.filter(r=>r.prior_self).length} 条目标已有自身命题。没有边不代表没有语义关联；候选匹配不是全配对。事件标签相邻也不表示彼此可见，同批节点横坐标相同。`;
let show=id=>{let n=byid[id];$('atomDetail').innerHTML=`<b>${E(n.text)}</b><br>${E(n.agent)} · ${g.roles[n.agent]} · E${n.event_id} · Quest ${n.quest} / proposal ${n.proposal}<br>${E(n.phase)} · ${E(n.visibility)} · ${E(n.modality)} · scope: ${E(n.scope)} · polarity: ${E(n.polarity)}<br><span class="small">mention_id: ${E(id)}</span>`};svg.querySelectorAll('[data-mid]').forEach(el=>{el.onclick=()=>show(el.dataset.mid);el.onkeydown=e=>{if(e.key==='Enter')show(el.dataset.mid)}});show(nodes[0].id)}
function init(){cov();camp();matrix();modalities();$('coverageMode').onchange=cov;['campChannel','campMode'].forEach(id=>$(id).onchange=camp);['matrixChannel','matrixMode'].forEach(id=>$(id).onchange=matrix);$('graphGame').innerHTML=Object.keys(S.atomic_cases).map(g=>`<option value="${g}">${g}</option>`).join('');$('graphGame').value='avalon-5p-10';$('graphGame').onchange=facts;$('graphTruth').onchange=facts;$('graphFact').onchange=graph;facts();$('truthTable').innerHTML='<table><tr><th>游戏</th><th>原子命题语义键</th><th>真值</th><th>公开 / 私有玩家数</th><th>首次公开角色</th><th>后续新增公开玩家</th></tr>'+S.truth_facts.map(r=>`<tr><td>${r.game}</td><td>${E(r.text)}<br><code>${E(r.key)}</code></td><td class="truth-${r.truth}">${r.truth?'真':'假'}</td><td>${r.public_agents} / ${r.private_agents}</td><td>${r.origin_roles.join(', ')}</td><td>${r.later_agents.map(p=>'P'+p).join(', ')||'无'}</td></tr>`).join('')+'</table>'}init();
'''
path=ROOT/'findings/2026-09-08-avalon-atomic-flow.html'
path.write_text(body+'<script>const S='+json.dumps(S,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')+';</script><script>'+js+'</script></html>')
print(path, path.stat().st_size)
